// The snapshot module's reading (tests/snapshot.ts): a file left with merge conflict markers is regenerated by an
// update run, and otherwise fails with what to do.
import { mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";
import { formatSnapshot, readStored, snapshotLayout, writeSnapshotFile } from "./snapshot.ts";
import { logFixtures, ROOT, shard } from "./logverdicts.ts";
import { renameKeys } from "../scripts/snapshot-keys.ts";
import { pendingCosts } from "../scripts/pending-costs.ts";
import { testTitle } from "./slow/pending.ts";
import type { VitestReport } from "../scripts/premerge.ts";

const dir = mkdtempSync(join(tmpdir(), "efsim-snapshot-"));
afterAll(() => rmSync(dir, { recursive: true, force: true }));

describe("reading a snapshot file", () => {
  const conflicted = join(dir, "conflicted.json");
  writeFileSync(conflicted, '{\n<<<<<<< HEAD\n "a": 1\n=======\n "a": 2\n>>>>>>> other\n}\n');

  it("starts from nothing when updating", () => {
    expect(readStored(conflicted, true)).toEqual({});
  });

  it("says to regenerate it otherwise", () => {
    expect(() => readStored(conflicted, false)).toThrow(/merge conflict markers.*snapshots:update/);
  });

  it("reads a good file and treats a missing one as empty", () => {
    const good = join(dir, "good.json");
    writeFileSync(good, '{"a": {"x": 1}}');
    expect(readStored(good, false)).toEqual({ a: { x: 1 } });
    expect(readStored(join(dir, "none.json"), false)).toEqual({});
  });
});

describe("writing a snapshot file", () => {
  it("every committed snapshot is in the one writer's layout (so a tool's rewrite and a regeneration agree)", () => {
    for (const f of readdirSync(join(ROOT, "tests", "snapshots")).filter((x) => x.endsWith(".json"))) {
      expect(snapshotLayout(readFileSync(join(ROOT, "tests", "snapshots", f), "utf8")), f).toBeDefined();
    }
  });

  it("renames keys by a pattern, keeps the layout, and refuses collisions (scripts/snapshot-keys.ts)", () => {
    const entries = { "pending/zmdlogs-a.json": { op: { plain: 1 } }, "pending/zmdlogs-b.json": { op: { plain: 2 } } };
    const r = renameKeys(entries, /^pending\/(zmdlogs-a)/, "holdout/$1");
    expect([r.renamed, r.total]).toEqual([1, 2]);
    expect(Object.keys(r.entries).sort()).toEqual(["holdout/zmdlogs-a.json", "pending/zmdlogs-b.json"]);
    const file = join(dir, "renamed.json");
    writeSnapshotFile(file, r.entries, true);
    const text = readFileSync(file, "utf8");
    expect(snapshotLayout(text)).toBe(true);
    expect(text).toBe(formatSnapshot(r.entries, true));
    expect(() => renameKeys(entries, /zmdlogs-[ab]/, "x")).toThrow(/two entries would have the key/);
  });
});

describe("the pending shards (tests/logverdicts.ts shard)", () => {
  const files = logFixtures("pending").slice(0, 12);

  it("split every log exactly once, by measured time where there is one", () => {
    const costs = Object.fromEntries(files.map((f, i) => [f, i === 0 ? 100 : 1]));
    const shards = [0, 1, 2, 3].map((i) => shard(files, 4, i, costs));
    expect(shards.flat().sort()).toEqual([...files].sort());
    // The one expensive log is alone in its shard's load: the other shards take the rest.
    expect(shards.find((s) => s.includes(files[0] as string))).toEqual([files[0]]);
  });

  it("read the check times from vitest's report (scripts/pending-costs.ts)", () => {
    const report: VitestReport = { testResults: [{ name: "/r/tests/slow/logs-pending-1.test.ts", status: "passed", assertionResults: [
      { status: "passed", fullName: "pending/zmdlogs-a.json checks as its snapshot says", failureMessages: [], duration: 12_345 },
      { status: "passed", fullName: "has a verdict snapshot for every pending fixture and none for a fixture that isn't one", failureMessages: [], duration: 5 },
    ] }] };
    expect(pendingCosts(report)).toEqual({ "pending/zmdlogs-a.json": 12.3 });
  });

  it("maps a hold-out's counter title back to its key, so no test title names a hold-out (tests/slow/pending.ts testTitle)", () => {
    const holdouts = ["holdout/zmdlogs-x.json", "holdout/zmdlogs-y.json"];
    expect(testTitle("holdout/zmdlogs-y.json", holdouts)).toBe("hold-out log 2");
    expect(testTitle("pending/zmdlogs-a.json", holdouts)).toBe("pending/zmdlogs-a.json");
    const report: VitestReport = { testResults: [{ name: "/r/tests/slow/logs-pending-1.test.ts", status: "passed", assertionResults: [{ status: "passed", fullName: "hold-out log 2 checks as its snapshot says", failureMessages: [], duration: 4_000 }] }] };
    expect(pendingCosts(report, holdouts)).toEqual({ "holdout/zmdlogs-y.json": 4 });
  });
});
